/* MK.Buildings AI Experts — interactive site.
 * All agent results come from window.MKB_DATA, generated by the Python agents
 * (scripts/export_site_data.py). No server, API or paid service is used. */
(function () {
  "use strict";

  const DATA = window.MKB_DATA;
  if (!DATA) {
    document.getElementById("main").insertAdjacentHTML("afterbegin",
      '<p class="note error container">Could not load agent data (data/site-data.js).</p>');
    return;
  }

  const ORCHESTRATOR = "CEO Orchestrator";
  const agentsByName = Object.fromEntries(DATA.agents.map(a => [a.name, a]));
  const namesLongestFirst = DATA.agents.map(a => a.name).sort((a, b) => b.length - a.length);

  // ---------- helpers ----------
  const $ = id => document.getElementById(id);
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const divClass = division => "div-" + String(division).toLowerCase().replace(/\s+/g, "-");
  const initials = name => {
    if (name === ORCHESTRATOR) return "CEO";
    const words = name.replace(/\(.*?\)/g, "").replace(/&/g, " ").split(/[\s,]+/).filter(w => /^[A-Za-z]/.test(w));
    return (words[0][0] + (words[1] ? words[1][0] : "")).toUpperCase();
  };
  const avatar = agent => `<span class="avatar" aria-hidden="true">${esc(initials(agent.name))}</span>`;

  const MONEY_KEYS = /(price|value|arv|cost|budget|profit|noi|rent|tax|insurance|service|flow|needed|offer|contingency|subtotal|sale|expenses|financing)/i;
  const PCT_KEYS = /(margin|cap_rate|cash_on_cash|return|rate)$/i;

  function label(key) {
    const words = key.replace(/_/g, " ");
    return words.charAt(0).toUpperCase() + words.slice(1);
  }

  function formatValue(key, value) {
    if (typeof value === "boolean") return value ? "Yes" : "No";
    if (typeof value === "number") {
      if (PCT_KEYS.test(key) && Math.abs(value) < 1.5 && !/millage/i.test(key)) return (value * 100).toFixed(1) + "%";
      if (MONEY_KEYS.test(key) && !/per_sqft|months|millage|dscr/i.test(key)) {
        return (value < 0 ? "-$" : "$") + Math.abs(Math.round(value)).toLocaleString("en-US");
      }
      return value.toLocaleString("en-US");
    }
    return esc(value);
  }

  function renderValue(key, value) {
    if (value === null || value === undefined) return "—";
    if (Array.isArray(value)) {
      if (value.length === 0) return "None";
      if (typeof value[0] === "object") {
        const rows = value.map(v => `<tr><td>${esc(v.item || v.address || "")}</td><td>${formatValue("cost", v.cost ?? v.price ?? "")}</td></tr>`).join("");
        return `<table class="kv">${rows}</table>`;
      }
      return value.map(v => esc(v)).join("<br>");
    }
    if (typeof value === "object") return renderTable(value);
    return formatValue(key, value);
  }

  function renderTable(obj) {
    const rows = Object.entries(obj)
      .map(([k, v]) => `<tr><th scope="row">${esc(label(k))}</th><td>${renderValue(k, v)}</td></tr>`).join("");
    return `<table class="kv">${rows}</table>`;
  }

  const list = (items, cls) => items.length ? `<ul class="${cls}">${items.map(i => `<li>${esc(i)}</li>`).join("")}</ul>` : "";

  // ---------- navigation ----------
  const navToggle = document.querySelector(".nav-toggle");
  const nav = $("site-nav");
  navToggle.addEventListener("click", () => {
    const open = nav.classList.toggle("open");
    navToggle.setAttribute("aria-expanded", String(open));
  });
  nav.addEventListener("click", e => {
    if (e.target.tagName === "A") { nav.classList.remove("open"); navToggle.setAttribute("aria-expanded", "false"); }
  });

  // ---------- experts directory ----------
  const divisions = ["All", ...new Set(DATA.agents.map(a => a.division))];
  let activeDivision = "All";
  const filtersEl = $("division-filters");
  filtersEl.innerHTML = divisions.map(d =>
    `<button class="filter" type="button" data-division="${esc(d)}" aria-pressed="${d === "All"}">${esc(d)}</button>`).join("");
  filtersEl.addEventListener("click", e => {
    const btn = e.target.closest(".filter");
    if (!btn) return;
    activeDivision = btn.dataset.division;
    filtersEl.querySelectorAll(".filter").forEach(b => b.setAttribute("aria-pressed", String(b === btn)));
    renderExperts();
  });
  $("expert-search").addEventListener("input", renderExperts);

  function renderExperts() {
    const q = $("expert-search").value.trim().toLowerCase();
    const shown = DATA.agents.filter(a =>
      (activeDivision === "All" || a.division === activeDivision) &&
      (!q || [a.name, a.role, ...a.responsibilities].join(" ").toLowerCase().includes(q)));
    $("expert-grid").innerHTML = shown.map(a => `
      <button class="expert-card ${divClass(a.division)}" type="button" data-name="${esc(a.name)}">
        <span class="expert-head">${avatar(a)}
          <span><span class="division-tag">${a.number === 0 ? "Leadership" : "#" + a.number + " · " + esc(a.division)}</span>
          <h3>${esc(a.name)}</h3></span>
        </span>
        <p>${esc(a.role)}</p>
        <span class="more">View details →</span>
      </button>`).join("") || '<p class="note">No experts match your search.</p>';
  }

  const dialog = $("expert-dialog");
  $("expert-grid").addEventListener("click", e => {
    const card = e.target.closest(".expert-card");
    if (card) openExpert(card.dataset.name);
  });

  function openExpert(name) {
    const a = agentsByName[name];
    const demoNames = { house: "House analysis", lot: "Vacant lot analysis" };
    $("dialog-body").innerHTML = `
      <div class="expert-head ${divClass(a.division)}">${avatar(a)}
        <div><span class="division-tag">${esc(a.division)}</span><h2 id="dialog-title">${esc(a.name)}</h2></div>
      </div>
      <p>${esc(a.role)}</p>
      <h4>Responsibilities</h4>${list(a.responsibilities, "")}
      <h4>Instructions it follows</h4>${list(a.instructions, "")}
      <h4>Inputs</h4><div class="chips">${a.inputs.map(i => `<span class="chip">${esc(i)}</span>`).join("")}</div>
      <h4>Outputs</h4><div class="chips">${a.outputs.map(i => `<span class="chip">${esc(i)}</span>`).join("")}</div>
      <h4>Appears in</h4><div class="chips">${a.demos.map(d => `<span class="chip">${esc(demoNames[d] || d)}</span>`).join("")}</div>`;
    if (typeof dialog.showModal === "function") dialog.showModal(); else dialog.setAttribute("open", "");
  }
  dialog.addEventListener("click", e => { if (e.target === dialog) dialog.close(); });

  // ---------- live demo ----------
  let scenario = null;
  let stepIndex = 0;
  let timer = null;

  $("scenario-picker").innerHTML = DATA.scenarios.map((s, i) => `
    <button class="scenario" role="tab" type="button" data-id="${esc(s.id)}" aria-selected="${i === 0}">
      <strong>${esc(s.title)}</strong><span>${esc(s.tagline)}</span>
    </button>`).join("");
  $("scenario-picker").addEventListener("click", e => {
    const btn = e.target.closest(".scenario");
    if (!btn) return;
    $("scenario-picker").querySelectorAll(".scenario").forEach(b => b.setAttribute("aria-selected", String(b === btn)));
    loadScenario(btn.dataset.id);
  });

  function agentInEntry(entry) {
    if (entry.startsWith(ORCHESTRATOR)) return ORCHESTRATOR;
    if (entry.startsWith("Founder")) return null;
    return namesLongestFirst.find(n => entry.startsWith(n)) || null;
  }

  function loadScenario(id) {
    stop();
    scenario = DATA.scenarios.find(s => s.id === id);
    stepIndex = 0;
    const s = scenario.subject;
    $("demo-request").textContent = `"${scenario.request}"`;
    const facts = {
      Address: s.address,
      Type: s.type || "Vacant lot",
      Size: s.sqft ? `${s.sqft.toLocaleString()} sq ft · ${s.bedrooms} bd / ${s.bathrooms} ba` : `${s.lot_sqft.toLocaleString()} sq ft lot`,
      "Asking price": "$" + s.asking_price.toLocaleString(),
      County: s.county,
      "Flood zone": s.flood_zone,
    };
    $("property-facts").innerHTML = Object.entries(facts).map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join("");
    const team = [ORCHESTRATOR, ...scenario.team];
    $("team-list").innerHTML = team.map(n => {
      const a = agentsByName[n];
      return `<li class="team-member ${divClass(a.division)}" data-name="${esc(n)}">${avatar(a)}<span>${esc(n)}</span><span class="status">Waiting</span></li>`;
    }).join("");
    $("activity-feed").innerHTML = "";
    $("report-grid").innerHTML = "";
    $("reports-section").hidden = true;
    $("memo-section").hidden = true;
    $("decision-result").innerHTML = "";
    setButtons();
  }

  function setStatus(name, status, text) {
    const el = $("team-list").querySelector(`[data-name="${CSS.escape(name)}"]`);
    if (!el) return;
    el.classList.remove("working", "done", "blocked", "skipped");
    if (status) el.classList.add(status);
    el.querySelector(".status").textContent = text;
  }

  function showStep() {
    const entry = scenario.activity_log[stepIndex];
    const name = agentInEntry(entry);
    const agent = agentsByName[name] || agentsByName[ORCHESTRATOR];
    let kind = "Update", cls = "";
    if (/ started$/.test(entry)) { kind = "Working"; setStatus(name, "working", "Working…"); }
    else if (/ finished: /.test(entry)) {
      kind = "Report filed";
      const blocked = /BLOCKED/.test(entry);
      setStatus(name, blocked ? "blocked" : "done", blocked ? "Blocked" : "Done");
      if (blocked) cls = "alert";
      addReport(name);
    } else if (/ reads the report from /.test(entry)) { kind = "Collaboration"; cls = "collab"; }
    else if (/double-checked/.test(entry)) { kind = "Double-check"; cls = "collab"; }
    else if (/stopped the workflow/.test(entry)) { kind = "Workflow stopped"; cls = "alert"; }
    else if (name === ORCHESTRATOR) { kind = "Orchestrator"; setStatus(ORCHESTRATOR, "working", "Coordinating"); }

    $("activity-feed").insertAdjacentHTML("beforeend",
      `<li class="feed-item ${cls} ${divClass(agent.division)}">${avatar(agent)}<div><span class="feed-kind">Step ${stepIndex + 1} · ${kind}</span>${esc(entry)}</div></li>`);
    const feed = $("activity-feed");
    feed.scrollTop = feed.scrollHeight;
    stepIndex += 1;
    if (stepIndex >= scenario.activity_log.length) finish();
    setButtons();
  }

  function addReport(name) {
    const r = scenario.reports[name];
    if (!r) return;
    const a = agentsByName[name];
    $("reports-section").hidden = false;
    $("report-grid").insertAdjacentHTML("beforeend", `
      <article class="report ${divClass(a.division)}">
        <h4>${esc(name)}</h4>
        <p class="summary">${esc(r.summary)}</p>
        ${r.warnings.length ? `<span class="label">Warnings</span>${list(r.warnings, "list-warn")}` : ""}
        ${r.licensed_actions.length ? `<span class="label">Licensed professionals needed</span>${list(r.licensed_actions, "list-lic")}` : ""}
        <details><summary>Show the numbers</summary>${renderTable(r.numbers)}
          ${r.sources.length ? `<span class="label">Sources</span>${list(r.sources, "list-src")}` : ""}
        </details>
      </article>`);
  }

  function finish() {
    stop();
    setStatus(ORCHESTRATOR, "done", "Memo sent");
    scenario.team.forEach(n => {
      if (!scenario.reports[n]) setStatus(n, "skipped", "Not needed");
    });
    $("memo-section").hidden = false;
    const blocked = Boolean(scenario.blocked_reason);
    const badge = $("memo-badge");
    badge.className = "badge" + (blocked ? " blocked" : "");
    badge.textContent = blocked ? "Blocked by Risk & Compliance" : "Waiting for Founder approval";
    const rec = $("memo-recommendation");
    rec.className = "recommendation" + (blocked ? " blocked" : "");
    rec.textContent = "Recommendation: " + scenario.recommendation;
    $("memo-text").textContent = scenario.memo;
    $("btn-approve").disabled = false;
    $("btn-reject").disabled = false;
  }

  function stop() { if (timer) { clearInterval(timer); timer = null; } $("btn-play").textContent = "▶ Play"; }

  function setButtons() {
    const total = scenario.activity_log.length;
    const done = stepIndex >= total;
    $("btn-step").disabled = done;
    $("btn-all").disabled = done;
    $("btn-play").disabled = done;
    $("demo-progress").textContent = `Step ${Math.min(stepIndex, total)} of ${total}`;
  }

  $("btn-play").addEventListener("click", () => {
    if (timer) { stop(); return; }
    $("btn-play").textContent = "❚❚ Pause";
    const delay = window.matchMedia("(prefers-reduced-motion: reduce)").matches ? 250 : 700;
    timer = setInterval(() => { if (stepIndex < scenario.activity_log.length) showStep(); }, delay);
  });
  $("btn-step").addEventListener("click", () => { stop(); if (stepIndex < scenario.activity_log.length) showStep(); });
  $("btn-all").addEventListener("click", () => { stop(); while (stepIndex < scenario.activity_log.length) showStep(); });
  $("btn-reset").addEventListener("click", () => loadScenario(scenario.id));

  // Founder decision — mirrors the Python rules in orchestrator.py
  $("btn-approve").addEventListener("click", () => {
    const out = $("decision-result");
    if (scenario.blocked_reason) {
      out.innerHTML = `<p class="note error"><strong>Approval refused.</strong> This deal is blocked by Risk &amp; Compliance: ${esc(scenario.blocked_reason)}. The problem must be fixed first.</p>`;
      return;
    }
    if (!scenario.after_approval) {
      out.innerHTML = '<p class="note">Approved, but the team recommends not proceeding, so no documents were prepared.</p>';
      return;
    }
    $("memo-badge").className = "badge approved";
    $("memo-badge").textContent = "Approved by the Founder";
    out.innerHTML = `<p><strong>Founder decision: APPROVED.</strong> The Acquisitions agent prepared this draft. It is <em>not sent</em>.</p><pre>${esc(scenario.after_approval)}</pre>`;
    $("btn-approve").disabled = true; $("btn-reject").disabled = true;
  });
  $("btn-reject").addEventListener("click", () => {
    $("memo-badge").className = "badge blocked";
    $("memo-badge").textContent = "Rejected by the Founder";
    $("decision-result").innerHTML = '<p class="note"><strong>Founder decision: REJECTED.</strong> Nothing is prepared or sent.</p>';
    $("btn-approve").disabled = true; $("btn-reject").disabled = true;
  });

  // ---------- start ----------
  renderExperts();
  loadScenario(DATA.scenarios[0].id);
})();
